@Component({ selector: 'app-prazos', ... })
export class PrazosComponent implements OnInit {
  ngOnInit(): void {
    // interval(1000) emite 0, 1, 2, 3... a cada 1 segundo
    interval(1000).subscribe(n => {
      console.log('tick ' + n);
    });
  }
}

export class ChatClienteComponent implements OnInit {
  mensagens: Mensagem[] = [];
  naoLidas = 0;

  ngOnInit(): void {
    // 1º subscribe: carrega o histórico via HTTP
    this.chatApi.listarMensagens(this.clienteId).subscribe(lista => {
      this.mensagens = lista;
    });

    // 2º subscribe: novaMensagem$ é um Subject do ChatHubService (providedIn: 'root')
    this.chatHub.novaMensagem$.subscribe(msg => {
      this.mensagens.push(msg);
      this.naoLidas++;
      this.tocarSom();
    });
  }
}

